(67, 'كارثة المضادات الحيوية واستخدامها بدون داعي 🤒', 'كارثة_المضادات_الحيوية_واستخدامها_بدون_داعي', 'https://www.youtube.com/embed/kI7RtJjeBrE?si=4yZhqsfwdsUTjI2d', 'learn-ST33.webp', 'حلقة المضادات الحيوية', 'ST', '', '', 'صحة وحياة', 'rtl', 'public', '2024-10-24', '2025-03-06 19:28:50', 'Unknown', 'all', 2, 75),
(68, 'الكافيين .. هل يسبب الإدمان ؟ | الاسبتالية', 'الكافيين_هل_يسبب_الإدمان_الاسبتالية', 'https://www.youtube.com/embed/738zhxOUkZo?si=Rom1RxfgYrcEy0sI', 'learn-ST34.webp', '\r\nالكافيين أكتر مادة دوائية بيتم استخدامها عالميا !\r\nوأكتر مادة منشطة عصبيا ونفسيا بيتم تعاطيها في العالم، إيه تأثيره على أجسامنا ؟ وليه بنعاني من أعراض انسحاب لو وقفنا تناوله بانتظام ؟ وهل يسبب الإدمان\r\n\r\n\r\n', 'ST', '', '', 'صحة وحياة', 'rtl', 'public', '2024-10-24', '2025-03-06 19:29:05', 'Unknown', 'all', 2, 75),
