(70, 'الإسبتالية - التجارب على البشر', 'الإسبتالية_التجارب_على_البشر', 'https://www.youtube.com/embed/xch0JSHHIVw?si=3z-R7-YmlijH0uw2', 'learn-ST36.webp', 'هل تقبل أن تكون فأر تجارب؟', 'ST', '', '', 'صحة وحياة, أصناف أخرى', 'rtl', 'public', '2024-10-24', '2025-03-06 19:29:30', 'Unknown', 'all', 15, 75),
(71, 'انتقام الميكروبات ! | هُدنة بعد الجائحة ؟', 'انتقام_الميكروبات_هُدنة_بعد_الجائحة', 'https://www.youtube.com/embed/6iHKICZwQkU?si=1EwDtQfbx5-sffOk', 'learn-ST37.webp', 'تصويتكم هو ما سيمكن زميلتنا سمية السيابية من اعتلاء منصة التتويج واحتضان لقب  ⁧‫#نجم_العلوم‬⁩ لهذا الموسم', 'st', '', '', 'صحة وحياة', 'rtl', 'public', '2024-10-24', '2025-03-06 19:29:41', 'Unknown', 'all', 2, 75),
(72, 'الاسبتالية من ألمانيا - كارثة المضادات الحيوية !', 'الاسبتالية_من_ألمانيا_كارثة_المضادات_الحيوية', 'https://www.youtube.com/embed/jm-PNBKRnEQ?si=C7Rvkq6lMRt73zhZ', 'learn-ST38.webp', 'إيه هي البكتيريا وإيه أمراضها وأضرارها ؟ يعني إيه مضاد حيوي ؟ وإيه الطريقة الأنسب لاستخدامه ؟ إيه الي هيحصل لو البكتيريا مابقتش تموت بالمضادات الحيوية اللي اخترعها الإنسان ؟ مين اللي هيكسب الحرب إحنا ولا البكتيريا اللي مابنقدرش نشوفها بعيوننا المجردة ؟\r\n', 'الاسبتالية من ألمانيا - كارثة المضادات الحيوية !', '', '', 'صحة وحياة', 'rtl', 'public', '2024-10-24', '2025-03-06 19:29:53', 'Unknown', 'all', 2, 75),
(73, 'إيه هي البكتيريا وإيه أمراضها وأضرارها ؟ يعني إيه مضاد حيوي ؟ وإيه الطريقة الأنسب لاستخدامه ؟ إيه الي هيحصل لو البكتيريا مابقتش تموت بالمضا', 'إيه_هي_البكتيريا_إيه_مضاد_حيوي', 'https://www.youtube.com/embed/OzTnFDgJEis?si=aUfINlCT5Nq2mp6e', 'sante_vih.webp', 'إتنين من الفيروسات اللي غيروا شكل عالمنا و هددوا حياة ملايين البشر\r\nإزاي تكاتفهم مع بعض ممكن يضاعف خساير البشر أضعاف ؟\r\nانهاردة 1 ديسمبر اليوم العالمي للتوعية ضد مرض الإيدز\r\nبنمر بيه واحنا عايشين جائحة الكورونا المستمرة من مارس اللي فات\r\nالحلقة دي من #الاسبتالية هي جزء من حملة منظمة الصحة العالمية للتوعية ضد مرض الإيدز\r\n World Health Organization (WHO)', 'الصحة، الإيدز، الإسبتالية', '', '', 'صحة وحياة', 'rtl', 'public', '2024-10-24', '2025-03-06 19:31:58', 'Unknown', 'all', 2, 75),
